/* Sporting Pearls — CSP-safe image fallback (Phase 5, R27 refactor;
 * portal copy, served from /portal/assets/img-fallback.js).
 *
 * Replaces every inline onerror="…" handler on the public pages AND the
 * portals so the Content-Security-Policy can drop script-src
 * 'unsafe-inline'.
 *
 * Markup contract (generated by the Phase 5 refactor):
 *   data-fb="<src>"          on load error, swap to this fallback image
 *   data-fb-hide="self"      if the fallback also fails (or no data-fb),
 *                            remove the <img> from the page
 *   data-fb-hide="parent"    …or hide the wrapping element instead
 *   data-fb-hide="reveal-next"  hide the <img> and show the next
 *                            sibling (the monogram avatar on the portal
 *                            player cards / parent child cards, which
 *                            ships with display:none)
 *
 * Load errors are caught with a capture-phase listener on window (error
 * events on <img> do not bubble but DO pass through capturing
 * ancestors), so dynamically inserted images are covered too.
 */
(function () {
  'use strict';
  function hasAttrs(img) {
    return img && img.tagName === 'IMG' &&
      (img.hasAttribute('data-fb') || img.hasAttribute('data-fb-hide'));
  }
  function act(img) {
    var fb = img.getAttribute('data-fb');
    if (fb && !img.getAttribute('data-fb-done')) {
      img.setAttribute('data-fb-done', '1');
      img.src = fb;
      return;
    }
    var how = img.getAttribute('data-fb-hide');
    if (how === 'reveal-next') {
      img.style.display = 'none';
      if (img.nextElementSibling) img.nextElementSibling.style.display = 'grid';
    } else if (how === 'parent' && img.parentElement) {
      img.parentElement.style.display = 'none';
    } else if (how === 'self') {
      img.remove();
    } else {
      img.style.visibility = 'hidden';
    }
  }
  window.addEventListener('error', function (e) {
    if (hasAttrs(e.target)) act(e.target);
  }, true);
  /* sweeps for images whose error fired before the listener existed
     (a fast/cached 404 can beat an end-of-body script) or while the
     image was still mid-load — at window.load every image has settled
     one way or the other. The synchronous first sweep runs at script
     execution: any error that already beat the script has certainly
     marked the image complete+broken by then. */
  function sweep() {
    var imgs = document.images, i;
    for (i = 0; i < imgs.length; i++) {
      var im = imgs[i];
      if (im.complete && im.naturalWidth === 0 && hasAttrs(im)) act(im);
    }
  }
  sweep();
  document.addEventListener('DOMContentLoaded', sweep);
  window.addEventListener('load', sweep);
})();
